# ------------------------------------------------------------------------------
cd "$PROJ" && zip -qr "../${PROJ}.zip" . -x "target/*" "artifacts/gdn_probe*" "tools/fixtures/*" && cd ..
zip -q "${PROJ}.zip" extract_repe_vectors.py
echo "Bootstrapped ${PROJ}/ (archive: ${PROJ}.zip)"
